package org.sleepwell.app;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.media.AudioManager;
import android.os.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Pattern;
import org.junit.Test;
import static org.junit.Assert.*;

/** Disposable-emulator first-use and real Android denial journeys. No alarm, sensor or audio output. */
public final class NightDialFirstNightTest {
 private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice d=UiDevice.getInstance(i);
 private interface Journey{void run(Scene scene)throws Exception;}
 private final class Scene implements AutoCloseable {
  final String name="first-night-"+UUID.randomUUID();final Map<String,?> preferences=new HashMap<>(Prefs.of(c).getAll());final Records.Factory records=Records.factory;final AlarmScheduling.Port scheduling=AlarmScheduling.port;final AlarmDefaultsSettings.Factory defaults=AlarmDefaultsSettings.factory;
  final AtomicInteger schedules=new AtomicInteger();final List<Activity> owned=new CopyOnWriteArrayList<>();final Application app=(Application)c.getApplicationContext();final AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);final int volume=audio.getStreamVolume(AudioManager.STREAM_ALARM);
  final Application.ActivityLifecycleCallbacks life=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
  Scene()throws Exception{
   assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());quiet();assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));assertTrue(Prefs.of(c).edit().clear().commit());
   Records.factory=context->new Store(context,name+".db");AlarmDefaultsSettings.factory=context->AlarmDefaultsSettings.of(c.getSharedPreferences(name+"-defaults",Context.MODE_PRIVATE));AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){schedules.incrementAndGet();}};app.registerActivityLifecycleCallbacks(life);
  }
  Store store(){return new Store(c,name+".db");}
  MainActivity main(){return (MainActivity)owned.stream().filter(a->a instanceof MainActivity&&!a.isFinishing()&&!a.isDestroyed()).reduce((a,b)->b).orElseThrow();}
  MainActivity launch(boolean launcher)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(MainActivity.class.getName(),null,false);try{Intent intent=new Intent(c,MainActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);if(launcher)intent.setAction(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);else intent.putExtra("destination",3);c.startActivity(intent);MainActivity found=(MainActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(found);d.waitForIdle();return found;}finally{i.removeMonitor(monitor);}}
  void recreate()throws Exception{MainActivity before=main();Instrumentation.ActivityMonitor monitor=i.addMonitor(MainActivity.class.getName(),null,false);try{i.runOnMainSync(before::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}d.waitForIdle();}
  void empty(){try(Store store=store()){assertTrue(store.alarms().isEmpty());assertTrue(store.rows("SELECT id FROM sessions").isEmpty());}assertEquals(0,schedules.get());quiet();}
  void quiet(){assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertNull(SleepSoundService.snapshot());assertFalse(MicrophoneLease.occupied());assertEquals(volume,audio.getStreamVolume(AudioManager.STREAM_ALARM));}
  public void close()throws Exception{
   d.pressHome();i.runOnMainSync(()->owned.forEach(a->{if(!a.isDestroyed())a.finish();}));i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+6000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(40);assertTrue("Owned first-use windows destroyed",owned.stream().allMatch(Activity::isDestroyed));app.unregisterActivityLifecycleCallbacks(life);quiet();Records.factory=records;AlarmScheduling.port=scheduling;AlarmDefaultsSettings.factory=defaults;
   SharedPreferences.Editor restore=Prefs.of(c).edit().clear();for(Map.Entry<String,?> entry:preferences.entrySet()){String key=entry.getKey();Object value=entry.getValue();if(value instanceof Boolean)restore.putBoolean(key,(Boolean)value);else if(value instanceof Integer)restore.putInt(key,(Integer)value);else if(value instanceof Long)restore.putLong(key,(Long)value);else if(value instanceof Float)restore.putFloat(key,(Float)value);else if(value instanceof String)restore.putString(key,(String)value);else if(value instanceof Set<?>)restore.putStringSet(key,new HashSet<>((Set<String>)value));else throw new AssertionError("Unsupported preference fixture type");}assertTrue(restore.commit());assertEquals(preferences,Prefs.of(c).getAll());c.deleteDatabase(name+".db");c.deleteSharedPreferences(name+"-defaults");
  }
 }
 private void scene(String name,Journey journey)throws Exception{try(Scene scene=new Scene()){try{journey.run(scene);}catch(Exception|AssertionError failure){File folder=new File(c.getExternalFilesDir(null),"verification");folder.mkdirs();d.takeScreenshot(new File(folder,"night-dial-first-"+name+"-failure.png"));d.dumpWindowHierarchy(new File(folder,"night-dial-first-"+name+"-failure.xml"));throw failure;}}}
 private UiObject2 text(String value){UiObject2 found=d.wait(Until.findObject(By.text(value)),5000);assertNotNull(value,found);return found;}
 private UiObject2 desc(String value)throws Exception{UiObject2 found=d.wait(Until.findObject(By.desc(value)),1200);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(value));found=d.wait(Until.findObject(By.desc(value)),5000);}assertNotNull(value,found);return found;}
 private UiObject2 readiness(String title)throws Exception{UiObject2 row=d.wait(Until.findObject(By.descStartsWith(title+" · ")),1200);if(row==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().descriptionStartsWith(title+" · "));row=d.wait(Until.findObject(By.descStartsWith(title+" · ")),5000);}assertNotNull(title,row);return row;}
 private void tap(String value)throws Exception{UiObject2 found=d.wait(Until.findObject(By.text(value)),1200);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(value));found=text(value);}found.click();d.waitForIdle();}
 private void capture(String name)throws Exception{NightDialCapture.frame(i,c,d,"first-"+name);}
 private void denyPermission()throws Exception{
  android.content.pm.ResolveInfo handler=c.getPackageManager().resolveActivity(new Intent("android.content.pm.action.REQUEST_PERMISSIONS"),PackageManager.MATCH_SYSTEM_ONLY);assertNotNull(handler);String controller=handler.activityInfo.packageName;
  UiObject2 deny=d.wait(Until.findObject(By.pkg(controller).res(Pattern.compile(".*:id/permission_deny_button")).enabled(true)),8000);assertNotNull("Actual Android denial action",deny);assertEquals(controller,d.getCurrentPackageName());deny.click();assertTrue(d.wait(Until.gone(By.pkg(controller).res(Pattern.compile(".*:id/permission_deny_button"))),8000));assertTrue(d.wait(Until.hasObject(By.pkg(c.getPackageName())),5000));d.waitForIdle();
 }
 @Test public void welcomeExploreAndAddFromDefaultsKeepExplicitSaveAuthority()throws Exception{scene("explore",scene->{
  scene.launch(true);text("Set up my night");text("Explore first");capture("welcome");scene.empty();assertTrue(Prefs.of(c).getAll().isEmpty());scene.recreate();text("Explore first");capture("welcome-restored");tap("Explore first");assertTrue(d.wait(Until.hasObject(By.desc("Tonight").selected(true)),5000));assertTrue(Prefs.flag(c,NightDialWelcome.DONE));assertEquals(Set.of(NightDialWelcome.DONE),Prefs.of(c).getAll().keySet());scene.launch(true);assertTrue(d.wait(Until.hasObject(By.desc("Tonight").selected(true)),5000));assertFalse(d.hasObject(By.text("Explore first")));capture("returning");
  Alarm template=new Alarm(91);template.volume=55;template.rampSeconds=90;template.setRoutine(new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Memory",2))));AlarmDefaultsSettings.factory.open(c).save(new AlarmDefaults(template));desc("Alarms").click();text("No alarms yet");capture("empty-alarms");desc("Add alarm").click();text("New alarm");assertFalse(desc("Alarm on").isChecked());desc("Name").click();UiObject2 name=d.wait(Until.findObject(By.clazz("android.widget.EditText").desc("Alarm name")),5000);assertNotNull(name);name.setText("Draft morning");tap("Use name");desc("Back").click();text("Save alarm changes?");tap("Discard");text("No alarms yet");scene.empty();desc("Add alarm").click();text("New alarm");assertFalse(desc("Alarm on").isChecked());capture("new-from-defaults");tap("Save alarm");desc("Edit A fresh start");try(Store store=scene.store()){Alarm saved=store.alarm(1);assertNotNull(saved);assertFalse(saved.enabled);assertEquals(55,saved.volume);assertEquals(90,saved.rampSeconds);assertTrue(saved.days.isEmpty());assertEquals("Memory",saved.challenges().tasks.get(0).type);assertEquals(2,saved.challenges().tasks.get(0).rounds);assertEquals(1,store.alarms().size());}assertEquals(1,scene.schedules.get());capture("saved-off");assertTrue(Prefs.of(c).edit().clear().commit());scene.launch(true);assertTrue(d.wait(Until.hasObject(By.desc("Tonight").selected(true)),5000));assertFalse(d.hasObject(By.text("Explore first")));try(Store store=scene.store()){assertNotNull(store.alarm(1));}capture("existing-user");scene.quiet();
 });}
 @Test public void firstSetupExplainsRestoresAndReturnsFromRealNotificationDenial()throws Exception{scene("notifications",scene->{
  assertEquals(PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS));scene.launch(true);tap("Set up my night");text("Get set for tonight");assertFalse(d.hasObject(By.descStartsWith("Microphone · ")));capture("readiness");scene.empty();readiness("Notifications").click();text("SleepWell uses notifications for:");text("Not now");capture("notifications-explanation");assertFalse(Prefs.flag(c,AlarmReadinessUi.NOTIFICATIONS_ASKED));scene.recreate();text("SleepWell uses notifications for:");capture("notifications-restored");assertFalse(Prefs.flag(c,AlarmReadinessUi.NOTIFICATIONS_ASKED));tap("Not now");text("Get set for tonight");scene.empty();readiness("Notifications").click();text("Continue to Android");tap("Continue to Android");denyPermission();text("Get set for tonight");text("Use app for now");assertEquals(PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS));assertEquals("Notifications · Not allowed",readiness("Notifications").getContentDescription());assertTrue(Prefs.flag(c,AlarmReadinessUi.NOTIFICATIONS_ASKED));capture("notifications-denied");scene.recreate();text("Use app for now");capture("denied-restored");readiness("Notifications").click();tap("Open Android settings");assertTrue(d.wait(Until.hasObject(By.pkg("com.android.settings")),8000));d.pressBack();text("Get set for tonight");assertEquals("Notifications · Not allowed",readiness("Notifications").getContentDescription());capture("notifications-returned");tap("Use app for now");assertTrue(d.wait(Until.hasObject(By.desc("Tonight").selected(true)),5000));assertEquals(PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.RECORD_AUDIO));assertFalse(Prefs.flag(c,AlarmReadinessUi.MIC_ASKED));scene.empty();
 });}
 @Test public void optionalMicrophoneRationaleRestoresWithoutStartingCapture()throws Exception{scene("microphone",scene->{
  assertEquals(PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.RECORD_AUDIO));scene.launch(false);tap("Reliability");text("Alarm readiness");assertEquals("Microphone · Optional",readiness("Microphone").getContentDescription());capture("regular-readiness");readiness("Microphone").click();denyPermission();assertTrue(Prefs.flag(c,AlarmReadinessUi.MIC_ASKED));readiness("Microphone").click();text("Allow microphone access?");capture("microphone-explanation");scene.recreate();text("Allow microphone access?");capture("microphone-restored");tap("Not now");text("Alarm readiness");assertEquals(PackageManager.PERMISSION_DENIED,c.checkSelfPermission(Manifest.permission.RECORD_AUDIO));assertEquals("Microphone · Optional",readiness("Microphone").getContentDescription());scene.empty();tap("Done");assertTrue(d.wait(Until.hasObject(By.desc("Settings").selected(true)),5000));assertFalse(Prefs.flag(c,"noiseEnabled"));
 });}
}
